HP.questSnapshotCount=0
for id,q in pairs(HP.questData) do if q.newForever and not snapshot[id] then q.snapshotUnavailable=true;q.navigationPending=true end end
for id,fields in pairs(snapshot) do
 HP.questSnapshotCount=HP.questSnapshotCount+1;local q=HP.questData[id]
 if not q or (q.name~=fields.name and (q.newForever or fields.newForever)) then q={goals={},navigationPending=true,prerequisitesUnverified=true,snapshotOnly=true};HP.questData[id]=q end
 for k,v in pairs(fields) do if k~='classes' or not q.classes then q[k]=v end end
 if q.startLocation then q.navigationPending=false end
 if q.newForever then HP.foreverQuests[id]=q end
 if fields.snapshotSide~='a' then
  for _,z in ipairs(HP.zoneCatalog) do if q.zoneID==z.areaID then
   local found=false;for _,list in ipairs({z.questIDs,z.newQuestIDs}) do for _,old in ipairs(list) do if old==id then found=true end end end
   if not found then local list=q.newForever and z.newQuestIDs or z.questIDs;list[#list+1]=id end
  end end
 end
end
